head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.pLIST_PROMT_SEQ = "";
scwin.listPromtSeq = "";
// 세션정보를 얻기위한 함수사용
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd"); // 오늘날짜

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        let url = frame.srcUrl;
        const arr = url.split("?");
        const arr2 = url.split("&");
        $c.cm.PanelToGroupBox(panel_Top);
        await scwin.init();
        if (arr2.length > 1) {
            cmb_INTVIEW_METHD_CD.setValue(arr2[1]);

            // setObjectValue(edt_INTIW_DD_TO, arr2[3]) ;
            cmb_PeriodTp.setValue(arr2[4]);
            edt_INTIW_DD_FROM.setValue(arr2[2]);
            edt_INTIW_DD_TO.setValue(arr2[3]);
        }
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF06004.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    const YY = scwin.vCurDate.substr(0, 4);
    const YY_1 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 1;
    const YY_2 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 2;
    const YY_3 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 3;
    const YY_4 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 4;
    edt_INTIW_DD_FROM.setValue(YY + "0101");
    edt_INTIW_DD_TO.setValue(YY + "1231");
    const strCbd_SME_YN = "전체^all," + YY + "^" + YY + "," + YY_1 + "^" + YY_1 + "," + YY_2 + "^" + YY_2 + "," + YY_3 + "^" + YY_3 + "," + YY_4 + "^" + YY_4 + "," + "기타^Z";
    cmb_PeriodTp.CBData = strCbd_SME_YN;

    // 담당자
    const sbmOptions = {
        id : "sbm_dts_EmpNo",
        action : "/ListPromtHistMgt.do",
        ref : "",
        target : "dts_EmpNo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "^전체";
    if (dts_EmpNo.getRowCount() > 0) {
        for (let i = 1; i <= dts_EmpNo.getRowCount(); i++) {
            strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_EmpNo.getCellData(i, "EMP_NO") + "^" + dts_EmpNo.getCellData(i, "DEP_EMP_NM");
        }
        cmb_EMP_NO.CBData = strCbd; //	담당자

    }
    cmb_EMP_NO.setSelectedIndex(0);
    const arrCid = [{
        cid: "INTVIEW_ACTIV_CD",
        cnm: "cmb_INTVIEW_METHD_CD"
    }, {
        cid: "VENT_ADM_INST_CD",
        cnm: "cmb_REL_INST_NM"
    }];
    let objCod;
    const sbmOptions2 = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "",
        i, j;
    for (let i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod === null) {
            await $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        if (arrCid[i].cid === 'INTVIEW_ACTIV_CD' || arrCid[i].cid === 'VENT_ADM_INST_CD') {
            strCbd = "^' '";
        }
        for (let j = 1; j <= dts_Cod.getRowCount(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        if ($c.stf.compareFromToDate2(edt_INTIW_DD_FROM, edt_INTIW_DD_TO)) {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF06004.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF06004.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF06004.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Excel_onclick = async function() {
    try {
        await scwin.excelDown();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF06004.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        scwin.setListPromtSeq(row);
        if ("ATTACH_FILE1" === colid && dts_List.getCellData(row, "ATTACH_FILE1") !== "") {
            // 파일첨부 1
            location.href = "/filedownload.do?SCREN_ID=" + "ULDSTF06004.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&LIST_PROMT_SEQ=" + scwin.pLIST_PROMT_SEQ + "&SEQ=1&gubun=41";
        } else if ("ATTACH_FILE2" === colid && dts_List.getCellData(row, "ATTACH_FILE2") !== "") {
            // 파일첨부 2
            location.href = "/filedownload.do?SCREN_ID=" + "ULDSTF06004.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&LIST_PROMT_SEQ=" + scwin.pLIST_PROMT_SEQ + "&SEQ=2&gubun=41";
        } else if ("ATTACH_FILE3" === colid && dts_List.getCellData(row, "ATTACH_FILE3") !== "") {
            // 파일첨부 3
            location.href = "/filedownload.do?SCREN_ID=" + "ULDSTF06004.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&LIST_PROMT_SEQ=" + scwin.pLIST_PROMT_SEQ + "&SEQ=3&gubun=41";
        } else {
            await scwin.openDetail(row);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF06004.grd_List_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_EDate_onclick
 * @description btn_EDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_EDate_onclick = function() {
    try {
        popUpCalendar2(edt_INTIW_DD_TO);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF06004.btn_EDate_onclick" });
    }
};

/**
