};

/**
 * @method
 * @name txb_COM_NM_onkeydown
 * @description txb_COM_NM 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_COM_NM_onkeydown = async function() {
    try {
        if (window.event.keyCode === 13) {
            if ($c.stf.compareFromToDate2(edt_INTIW_DD_FROM, edt_INTIW_DD_TO)) {
                await scwin.listSync();
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF06004.txb_COM_NM_onkeydown" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF06004.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnRowPosChanged
