 * @hidden N
 */
scwin.btn_Input_onclick = async function() {
    try {
        await scwin.openDetail(-1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF06004.btn_Input_onclick" });
    }
};

/**
 * @method
 * @name btn_Input_Excel_onclick
 * @description 「입력」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Input_Excel_onclick = async function() {
    try {
        const inputType = cmb_INPUT_EXCEL_TP_CD.getValue();
        if (inputType === "1") {
            const options = {
                id: "ULDSTF06010",
                title: "주관계약체결 등록",
                type: "browserPopup",
                width: "740px",
                height: "400px",
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("/lstmgt/ULDSTF06010.gfm", options);
        } else if (inputType === "2") {
            const options = {
                id: "ULDSTF06011",
                title: "상장교육수료일 등록",
                type: "browserPopup",
                width: "740px",
                height: "400px",
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("/lstmgt/ULDSTF06011.gfm", options);
        } else if (inputType === "3") {
            const options = {
                id: "ULDSTF06012",
                title: "유관기관 등록",
                type: "browserPopup",
                width: "740px",
                height: "400px",
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("/lstmgt/ULDSTF06012.gfm", options);
        } else if (inputType === "4") {
            const options = {
                id: "ULDSTF06013",
                title: "재무정보 등록",
                type: "browserPopup",
                width: "740px",
                height: "400px",
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("/lstmgt/ULDSTF06013.gfm", options);
        } else if (inputType === "5") {
            const options = {
                id: "ULDSTF06014",
                title: "투자유치 등록",
                type: "browserPopup",
                width: "740px",
                height: "400px",
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("/lstmgt/ULDSTF06014.gfm", options);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF06004.btn_Input_Excel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description 상장유치실적조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    url += "&inputMessageId=LISTPROMTPRFMKOLIST_IN&outputMessageId=LISTPROMTPRFMKOLIST_INOUT";
    url += "&INTIW_DD_TYPE=" + cmb_PeriodTp.getValue();
    url += "&INTIW_DD_FROM=" + edt_INTIW_DD_FROM.getValue();
    url += "&INTIW_DD_TO=" + edt_INTIW_DD_TO.getValue();
    url += "&COM_NM=" + txb_COM_NM.getValue();
    url += "&EMPLOYEE_NO=" + cmb_EMP_NO.getValue();
    url += "&EMPLOYEE_NM=" + cmb_EMP_NO.getText();
    url += "&CORP_REG_NO=" + txb_CORP_REG_NO.getValue();
    url += "&MAJAGNT_CONTRT_TRD_YN=" + chk_MAJAGNT_CONTRT_TRD_YN.getValue();
    url += "&LIST_EDU_YN=" + chk_LIST_EDU_YN.getValue();
    url += "&EXT_AUDT_YN=" + chk_EXT_AUDTR_YN.getValue();
    url += "&REL_INST_NM=" + cmb_REL_INST_NM.getValue();
    url += "&INTVIEW_METHD_CD=" + cmb_INTVIEW_METHD_CD.getValue();
    url += "&CAP_TOTAMT_FROM=" + edt_CAP_TOTAMT_FROM.getValue();
    url += "&CAP_TOTAMT_TO=" + edt_CAP_TOTAMT_TO.getValue();
    url += "&SALES_FROM=" + edt_SALES_FROM.getValue();
    url += "&SALES_TO=" + edt_SALES_TO.getValue();
    url += "&BZ_PROFT_AMT_FROM=" + edt_BZ_PROFT_AMT_FROM.getValue();
    url += "&BZ_PROFT_AMT_TO=" + edt_BZ_PROFT_AMT_TO.getValue();
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/ListPromtHistMgt.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    const rtn = confirm("'" + dts_List.getCellData(dts_List.getRowPosition(), "COM_NM") + "'" + ' 항목을 삭제하시겠습니까?');
    if (rtn === 1) {
        let trsIdx = "";
        trsIdx = TR_JOB_DELETE;
        // dts_ContentsDel.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        dts_ContentsDel.insertRow();
        scwin.listPromtSeq = dts_List.getCellData(dts_List.getRowPosition(), "LIST_PROMT_SEQ");
        dts_ContentsDel.setCellData(1, "LIST_PROMT_SEQ", dts_List.getCellData(dts_List.getRowPosition(), "LIST_PROMT_SEQ"));
        // [전환검토] trs_Delete.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     TRS_IDX : trsIdx,
        //     LIST_PROMT_SEQ : scwin.listPromtSeq
        // };
        const sbmOptions = {
            id : "sbm_trs_Delete",
            action : "/ListPromtHistMgt.do",
            ref : "dts_ContentsDel",
            target : "trs_Delete=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
