 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setDate
 * @description 면담일 연도별검색Setting
 * @param {*} pYear pYear
 * @returns {void}
 * @hidden N
 */
scwin.setDate = function(pYear) {
    if (pYear === "all" || pYear === "Z") {
        edt_INTIW_DD_FROM.setValue("");
        edt_INTIW_DD_TO.setValue("");
    } else {
        edt_INTIW_DD_FROM.setValue(pYear + "0101");
        edt_INTIW_DD_TO.setValue(pYear + "1231");
    }
};

/**
 * @method
 * @name excelDown
 * @description 정보를 excel로 다운 받는다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDown = async function() {
    if (dts_List.getRowCount() > 0) {
        $c.stf.doLogSave("ULDSTF06004.xml", SCREN_PROCS_TP_CD_01);
        $c.data.downloadGridViewExcel(grd_List, {fileName: "기업정보 조회", type: "3"});
    } else {
        await $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};

/**
 * @method
 * @name openDetail
 * @description OnDblClick Event 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetail = async function(row) {
    let pageNM;
    scwin.setListPromtSeq(row);
    pageNM = "ULDSTF06003";
    const options = {
        id: "" + pageNM + "",
        title: " 기업정보 입력",
        type: "browserPopup",
        width: "1265px",
        height: "860px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/lstmgt/" + pageNM + ".gfm", options);
};

/**
 * @method
 * @name setListPromtSeq
 * @description set List Promt Seq 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setListPromtSeq = function(obj) {
    scwin.pLIST_PROMT_SEQ = dts_List.getCellData(Number(obj), "LIST_PROMT_SEQ");
};

/**
 * @method
 * @name getListPromtSeq
 * @description get List Promt Seq 처리
 * @returns {void}
 * @hidden N
 */
scwin.getListPromtSeq = function() {
    return scwin.pLIST_PROMT_SEQ;
};
